#ifdef HAVE_ROM
static uint8_t ram[marble_physics::RAM_SIZE];

// Fixture work RAM: zero except the recorded blocks.
static void loadRam(const MarbleTraceSegment &seg) {
  memset(ram, 0, sizeof(ram));
  for (uint8_t i = 0; i < seg.nram; i++) {
    const MarbleTraceRam &r = seg.ram[i];
    memcpy(ram + (r.addr - marble_physics::RAM_BASE), r.bytes, r.len);
  }
}

// A fixture snapshot is the 0x121b8 entry of a state 0/1 handler: finish that tick (internals
// of the included marble_physics.cpp). Fixture tick k + 1 is then one tick() with the deltas
// stored at tick k.
static void finishTick(marble_physics::Mem &m) {
  const uint8_t st = marble_physics::state(m);
  marble_physics::physics_121b8(m, marble_physics::PLAYER);
  if (st == marble_physics::DIZZY) { marble_physics::countdown_2574c(m, marble_physics::PLAYER); }
}

static void test_replay_trace(void) {
  for (uint8_t s = 0; s < MARBLE_TRACE_SEGMENTS; s++) {
    const MarbleTraceSegment &seg = marble_trace_segments[s];
    loadRam(seg);
    marble_physics::Mem m(ram, seg.race);

    for (uint16_t k = 0; k < seg.nticks; k++) {
      const MarbleTraceTick &t = seg.ticks[k];
      if (k == 0) {
        finishTick(m);
      } else {
        marble_physics::tick(m, seg.ticks[k - 1].c6, seg.ticks[k - 1].c7);
      }

      const int32_t x = marble_physics::x(m), y = marble_physics::y(m), z = marble_physics::z(m);
      const uint8_t st = marble_physics::state(m);
      if (x == t.x && y == t.y && z == t.z && st == t.state) { continue; }

      char msg[200];
      snprintf(msg, sizeof(msg),
               "segment %d (race %d frame %u) tick %d: expected x %08x y %08x z %08x state %d,"
               " got x %08x y %08x z %08x state %d",
               s, seg.race, (unsigned)seg.frame, k, (unsigned)t.x, (unsigned)t.y, (unsigned)t.z,
               t.state, (unsigned)x, (unsigned)y, (unsigned)z, st);
      TEST_FAIL_MESSAGE(msg);
    }
  }
}

// Every dynamic terrain code (0x0800-0x0fff) of a race has its slot set at race start;
// 0 would be no floor.
static void test_dyn_init(void) {
  for (uint8_t race = 0; race < 6; race++) {
    memset(ram, 0, sizeof(ram));
    marble_physics::Mem m(ram, race);
    marble_physics::startRace(m, race);

    for (int16_t d = 0; d < m.maxd(); d += 2) {
      for (int16_t f = 0; f < 44; f++) {
        const uint16_t c = m.vertexCode(d, f);
        if (c < 0x800 || c >= 0x1000) { continue; }
        if (m.rw(marble_physics::DYN + (c & 0x7fe))) { continue; }

        char msg[80];
        snprintf(msg, sizeof(msg), "race %d diagonal %d: dynamic code %04x not set", race, d, c);
        TEST_FAIL_MESSAGE(msg);
      }
    }
  }
}

// 0x13a98 reduces with a signed compare (cmp.w, bgt): for n >= 0x8000 (the catapult's
// rng(0xa000)) the result lies in 0x8000..n-1 (MAME a10: vy -0x25000 - 0x8f4a). Values from
// marble_sim.py rng_13a98: seed, n, result, seed after.
static void test_rng_signed(void) {
  static const uint16_t CASES[][4] = {
      {0x1234, 0xa000, 0x8cf1, 0x4cf1}, {0x1234, 0x2000, 0x133c, 0x133c},
      {0x8f00, 0xa000, 0x9e3c, 0x1e3c}, {0xbeef, 0xa000, 0x829a, 0xa29a},
      {0xbeef, 0x0100, 0x0045, 0xdf45}, {0x5a5a, 0xa000, 0x81b6, 0x81b6},
      {0xffff, 0xa000, 0x9fff, 0xffff}, {0x0001, 0x0002, 0x0000, 0x0004},
  };
  static const uint32_t STATE = 0x4003a6;
  memset(ram, 0, sizeof(ram));
  marble_physics::Mem m(ram, 0);
  for (const uint16_t *c : CASES) {
    m.ww(STATE, c[0]);
    TEST_ASSERT_EQUAL_HEX16(c[2], marble_rng::rng(m, c[1]));
    TEST_ASSERT_EQUAL_HEX16(c[3], m.rw(STATE));
  }
}
#endif

int main(int, char **) {
  UNITY_BEGIN();
#ifdef HAVE_ROM
  RUN_TEST(test_replay_trace);
  RUN_TEST(test_dyn_init);
  RUN_TEST(test_rng_signed);
#else
  TEST_IGNORE_MESSAGE("marble_rom.h missing, run romconv ./convert.sh marble");
#endif
  return UNITY_END();
}
